const REQUIRED_COLUMNS = ['brandname', 'revenue', 'Order', 'Boss Gmail', 'week_start'];
const isBlank = (value) => value === '' || value === null || value === undefined;

const rows = $input.all().map((item) => item.json);

// 1. Every column the rule needs must exist.
const missing = REQUIRED_COLUMNS.filter((column) => !(column in (rows[0] ?? {})));
if (missing.length > 0) {
  throw new Error(`Sheet is missing column(s): ${missing.join(', ')}`);
}

// 2. A hotel row has at least one number or an email. This drops blank rows and the note in row 14,
//    but keeps a real hotel with a missing email so the next step can send it for review.
const hotels = rows.filter((row) => !isBlank(row.revenue) || !isBlank(row.Order) || !isBlank(row['Boss Gmail']));
if (hotels.length === 0) {
  throw new Error('Sheet has no hotel rows');
}

// 3. The data must be last week's. Weeks start on Monday.
const expectedWeek = $now.startOf('week').minus({ weeks: 1 }).toISODate();
const foundWeeks = [...new Set(hotels.map((row) => String(row.week_start)))];
if (foundWeeks.length !== 1 || foundWeeks[0] !== expectedWeek) {
  throw new Error(`Sheet is not last week's data: expected week_start ${expectedWeek}, found ${foundWeeks.join(', ')}`);
}

return hotels.map((json) => ({ json }));

const BELOW_SHARE = 0.6;   // below 60% of the peer median = below usual
const ABOVE_SHARE = 1.4;   // above 140% of the peer median = above usual (same distance from the median)
const MIN_PEERS = 5;       // with fewer hotels the comparison means little, so a person decides

const hotels = $input.all().map((item) => item.json);
const isBlank = (value) => value === '' || value === null || value === undefined;

// Why a row can't be labelled automatically. null means the row is fine.
function findProblem(hotel) {
  const email = String(hotel['Boss Gmail'] ?? '').trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return 'Owner email is missing or invalid';
  if (typeof hotel.revenue !== 'number' || typeof hotel.Order !== 'number') return 'Revenue or orders is not a number';
  if (hotel.revenue < 0 || hotel.Order < 0) return 'Revenue or orders is negative';
  if (hotel.revenue === 0 || hotel.Order === 0) return 'Revenue or orders is zero';
  if (!isBlank(hotel.target_revenue) && !(typeof hotel.target_revenue === 'number' && hotel.target_revenue > 0)) return 'Target is not a valid number';
  return null;
}

function median(values) {
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

function band(value, peerMedian) {
  if (value < peerMedian * BELOW_SHARE) return 'below';
  if (value > peerMedian * ABOVE_SHARE) return 'above';
  return 'in_range';
}

const problems = hotels.map(findProblem);

// Medians use normal rows only, so one bad row can't move the line for everyone.
const peers = hotels.filter((hotel, index) => problems[index] === null);
const enoughPeers = peers.length >= MIN_PEERS;
const revenueMedian = enoughPeers ? median(peers.map((hotel) => hotel.revenue)) : null;
const ordersMedian = enoughPeers ? median(peers.map((hotel) => hotel.Order)) : null;
const perOrderMedian = enoughPeers ? median(peers.map((hotel) => hotel.revenue / hotel.Order)) : null;

return hotels.map((hotel, index) => {
  let reviewReason = problems[index];
  if (reviewReason === null && !enoughPeers) reviewReason = `Fewer than ${MIN_PEERS} hotels to compare`;
  const canCompare = reviewReason === null;
  const hasTarget = canCompare && !isBlank(hotel.target_revenue);

  // Only revenue decides the label: against the hotel's own target if it has one, otherwise against the group.
  // Orders and revenue per order explain the result.
  let revenueStatus = null;
  if (hasTarget) revenueStatus = hotel.revenue >= hotel.target_revenue ? 'met' : 'missed';
  else if (canCompare) revenueStatus = band(hotel.revenue, revenueMedian);

  const isLow = revenueStatus === 'below' || revenueStatus === 'missed';
  const label = !canCompare ? 'review' : isLow ? 'needs_improvement' : 'good';

  const canDivide = typeof hotel.revenue === 'number' && typeof hotel.Order === 'number' && hotel.Order > 0;

  return {
    json: {
      hotel: hotel.brandname,
      revenue: hotel.revenue,
      orders: hotel.Order,
      revenue_per_order: canDivide ? Math.round(hotel.revenue / hotel.Order) : null,
      owner_email: hotel['Boss Gmail'],
      week_start: hotel.week_start,
      label,
      review_reason: reviewReason,
      revenue_status: revenueStatus,
      orders_status: canCompare ? band(hotel.Order, ordersMedian) : null,
      revenue_per_order_status: canCompare ? band(hotel.revenue / hotel.Order, perOrderMedian) : null,
      target_revenue: hasTarget ? hotel.target_revenue : null,
      // Rounded down, so a hotel just short of its target never shows 100%.
      target_percent: hasTarget ? Math.floor((hotel.revenue / hotel.target_revenue) * 100) : null,
    },
  };
});

