const MAX_CHARS = 300;
const SUBJECT_LEAD = { below: 'Worth a closer look', missed: 'Below target', in_range: 'In the usual range', above: 'Above the usual range', met: 'Target met' };
const STATUS_TEXT = { below: 'Below usual', missed: 'Below target', in_range: 'In range', above: 'Above usual', met: 'Target met' };
// Orange rather than red: below usual means lower than this group this week, not bad performance.
const STATUS_COLOR = { below: '#C2410C', missed: '#C2410C', in_range: '#5F6368', above: '#137333', met: '#137333' };
const NEUTRAL_COLOR = '#5F6368';

// Word lists catch what they list. An indirect sentence can still pass, so needs-improvement emails still go to a person.
const BANNED = [
  ['a number', /[0-9๐-๙０-９%]|\b(hundred|thousand|million|billion|percent|half|double|twice)\b/i],
  ['a leftover placeholder', /[{}\[\]]/],
  // The group is every partner hotel in the sheet, not hotels like this one, so similar is a false claim.
  ['data we do not have', /\b(last week|previous|compared (with|to)|similar|comparable|occupancy|adr|revpar|room rate|forecast)\b/i],
  ['a ranking', /\b(highest|lowest|ranked?|leading|top of)\b/i],
  ['a made-up cause', /\b(because|due to|caused|driven|thanks to|result of|leads? to|led to|reason|seasons?|seasonal|weather|holidays?|competitors?|as a result)\b/i],
  ['blame', /\b(fail\w*|poor\w*|bad\w*|terrible|disappoint\w*)\b/i],
];
const PRAISE = /\b(great|excellent|congrat\w*|well done|outstanding|fantastic|impressive)\b/i;
const WARNING = /\b(improve\w*|concern\w*|closer look|worry\w*)\b/i;

const LOW_WORDS = /\b(below|under|low\w*|less|fewer|weak\w*|short)\b/i;
const HIGH_WORDS = /\b(above|over|high\w*|more|exceed\w*|beat\w*|strong\w*)\b/i;
const USUAL_WORDS = /\b(in range|in the usual|within|usual range|normal|typical)\b/i;
const DIRECTION_OF_STATUS = { below: 'low', missed: 'low', in_range: 'usual', above: 'high', met: 'high' };

function directionOf(text) {
  if (LOW_WORDS.test(text)) return 'low';
  if (HIGH_WORDS.test(text)) return 'high';
  if (USUAL_WORDS.test(text)) return 'usual';
  return null;
}

function measureOf(text) {
  if (/revenue per order/i.test(text)) return 'revenue_per_order_status';
  if (/\borders?\b/i.test(text)) return 'orders_status';
  if (/\brevenue\b/i.test(text)) return 'revenue_status';
  return null;
}

// Does each part of the summary say what the rules decided about that measure?
function findWrongStatuses(summary, hotel) {
  const problems = [];
  const directions = ['revenue_status', 'orders_status', 'revenue_per_order_status'].map((key) => DIRECTION_OF_STATUS[hotel[key]]);
  if (LOW_WORDS.test(summary) && !directions.includes('low')) problems.push('summary says something is low, but nothing is');
  if (HIGH_WORDS.test(summary) && !directions.includes('high')) problems.push('summary says something is high, but nothing is');
  for (const part of summary.split(/[.;,:!?]|\b(?:but|while|and|though|although|however|with|yet)\b/i)) {
    const measure = measureOf(part);
    const direction = directionOf(part);
    if (measure && direction && direction !== DIRECTION_OF_STATUS[hotel[measure]]) {
      problems.push(`summary gives the wrong status for ${measure.replace('_status', '').replace(/_/g, ' ')}`);
    }
  }
  return problems;
}

// The distinctive parts of a hotel name: Chinese name, and English name without generic words like Inn.
function namesOf(brandname) {
  const parts = String(brandname).split(' ');
  const english = parts.slice(1).join(' ').replace(/\s+(Inn|Hotel|Hostel|Resort|Biz)$/i, '');
  return [parts[0], english].filter(Boolean);
}

function findProblems(draft, hotel, otherNames) {
  if (!draft) return ['AI gave no usable answer'];
  const problems = [];
  const praiseAllowed = hotel.revenue_status === 'above' || hotel.revenue_status === 'met';
  for (const field of ['summary', 'next_step']) {
    const text = draft[field];
    if (typeof text !== 'string' || text.trim() === '') { problems.push(`${field} is missing`); continue; }
    if (text.length > MAX_CHARS) problems.push(`${field} is too long`);
    for (const [name, pattern] of BANNED) if (pattern.test(text)) problems.push(`${field} has ${name}`);
    if (hotel.target_revenue === null && /\b(target|goal)\b/i.test(text)) problems.push(`${field} mentions a target this hotel does not have`);
    if (!praiseAllowed && PRAISE.test(text)) problems.push(`${field} has praise that does not match the result`);
    if (hotel.label === 'good' && WARNING.test(text)) problems.push(`${field} has a warning that does not match the result`);
    if (otherNames.some((name) => text.toLowerCase().includes(name.toLowerCase()))) problems.push(`${field} names another hotel`);
  }
  if (typeof draft.summary === 'string') problems.push(...findWrongStatuses(draft.summary, hotel));
  return problems;
}

const escapeHtml = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const formatNumber = (value) => value.toLocaleString('en-US');

function figureRow(name, value, badgeText, badgeColor) {
  const badge = `<span style="display:inline-block;padding:2px 8px;border-radius:10px;background-color:${badgeColor};color:#ffffff;font-size:13px;white-space:nowrap">${badgeText}</span>`;
  return `<tr><td style="padding:6px 8px 6px 0;border-bottom:1px solid #999">${name}</td>`
    + `<td align="right" style="padding:6px 12px;border-bottom:1px solid #999;white-space:nowrap">${formatNumber(value)}</td>`
    + `<td style="padding:6px 0;border-bottom:1px solid #999;white-space:nowrap">${badge}</td></tr>`;
}

const statusRow = (name, value, status) => figureRow(name, value, STATUS_TEXT[status], STATUS_COLOR[status]);

function closingNote(hotel) {
  const comparison = hotel.target_revenue === null
    ? 'Compared with partner hotels for one week.'
    : 'Revenue is compared with your target. Orders and revenue per order are compared with partner hotels for one week.';
  return `${comparison} Room count and hotel type are not included. Reply if a figure looks wrong.`;
}

// Colour only on the status badges, each with its own white text, so dark mode can't hide them.
function buildEmail(hotel, summary, nextStep, period) {
  const targetRow = hotel.target_revenue === null
    ? ''
    : figureRow('Target', hotel.target_revenue, `${hotel.target_percent}% reached`, NEUTRAL_COLOR);
  return `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;max-width:480px">`
    + `<p style="margin:0"><strong>${escapeHtml(hotel.hotel)}</strong></p>`
    + `<p style="margin:0 0 16px">${period}</p>`
    + `<p style="margin:0 0 16px">${escapeHtml(summary)}</p>`
    + `<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:0 0 16px">`
    + statusRow('Revenue', hotel.revenue, hotel.revenue_status)
    + targetRow
    + statusRow('Orders', hotel.orders, hotel.orders_status)
    + statusRow('Revenue per order', hotel.revenue_per_order, hotel.revenue_per_order_status)
    + `</table>`
    + `<p style="margin:0 0 16px"><strong>One thing to try:</strong> ${escapeHtml(nextStep)}</p>`
    + `<p style="margin:0;font-size:13px">${closingNote(hotel)}</p>`
    + `</div>`;
}

const hotels = $('Add Approved Wording').all().map((item) => item.json);
const allNames = $('Apply Label Rule').all().map((item) => item.json.hotel);

return $input.all().map((item, index) => {
  const hotel = hotels[item.pairedItem?.item ?? index];
  const otherNames = allNames.filter((name) => name !== hotel.hotel).flatMap(namesOf);

  const start = DateTime.fromISO(hotel.week_start).setLocale('en');
  const period = `${start.toFormat('d LLL')} - ${start.plus({ days: 6 }).toFormat('d LLL yyyy')}`;

  const draft = item.json.output;
  const problems = findProblems(draft, hotel, otherNames);
  const usedTemplate = problems.length > 0;

  const body = usedTemplate
    ? buildEmail(hotel, hotel.approved_point, hotel.approved_next_step, period)
    : buildEmail(hotel, draft.summary.trim(), draft.next_step.trim(), period);

  // Last guard: every number the reader sees must be this hotel's own figure, part of its name, or part of the date.
  const visibleText = body.replace(/<[^>]*>/g, ' ').replace(/(\d),(?=\d)/g, '$1');
  const allowed = new Set(
    [hotel.revenue, hotel.orders, hotel.revenue_per_order, hotel.target_revenue, hotel.target_percent].filter((value) => value !== null).map(String)
      .concat(period.match(/\d+/g), String(hotel.hotel).match(/\d+/g) ?? [])
  );
  const strayNumbers = (visibleText.match(/\d+/g) ?? []).filter((number) => !allowed.has(number));
  if (strayNumbers.length > 0) {
    throw new Error(`${hotel.hotel}: email has numbers that are not in the data: ${strayNumbers.join(', ')}`);
  }

  const labelNote = hotel.revenue_status === 'missed' ? 'Revenue is below the target.' : 'Revenue is below the usual range.';

  return {
    json: {
      hotel: hotel.hotel,
      owner_email: hotel.owner_email,
      label: hotel.label,
      subject: `${SUBJECT_LEAD[hotel.revenue_status]} | ${hotel.hotel}`,
      body,
      summary_text: usedTemplate ? hotel.approved_point : draft.summary.trim(),
      used_template: usedTemplate,
      check_problems: problems,
      needs_review: hotel.label !== 'good' || usedTemplate,
      review_note: usedTemplate ? `AI draft failed the check (${problems.join('; ')}), so this uses the template.` : labelNote,
    },
    pairedItem: item.pairedItem,
  };
});
